/*GT_TT_STEAL_BEGIN*/
// Plus/Minus-Karte (Tutto-Anleitung): wer ein Tutto schafft, bekommt 1000; jedem Fuehrenden werden 1000 abgezogen,
// bei Gleichstand allen Fuehrenden. Der Werfende zieht sich selbst nie etwas ab. Gibt die neuen Spieler und die Betroffenen zurueck.
function ttSteal(players,sel){if(!Array.isArray(players)||sel<0||sel>=players.length)return null;const tot=players.map(p=>(p.entries||[]).reduce((s,e)=>s+e,0));const max=Math.max(...tot);const losers=tot.map((v,i)=>v===max&&i!==sel?i:-1).filter(i=>i>=0);const next=players.map((p,i)=>i===sel?{...p,entries:[...p.entries,1000]}:losers.includes(i)?{...p,entries:[...p.entries,-1000]}:p);return{players:next,losers};}
/*GT_TT_STEAL_END*/
